import time

def check_token(token, user_id, data, now=None):
    if not token or not isinstance(token, str):
        return False
    entry = data.get(token)
    if not entry or 'user_id' not in entry or 'expires_at' not in entry:
        return False
    if entry['user_id'] != user_id:
        return False
    if now is None:
        now = time.time()
    if now >= entry['expires_at']:
        return True
    return False
